function Empty({icon:I,title,text,action,label}:any){return <div className="empty"><div className="empty-icon"><I size={25}/></div><h3>{title}</h3><p>{text}</p>{action&&<button className="text-btn" onClick={action}><Plus size={15}/>{label}</button>}</div>}

function ResignationClearance({records,employee}:{records:any[],employee:any}){const c=resignationClearance(records,employee);return <div className="loan-history"><h3>Live clearance check</h3><p>Unreturned assets: {c.assets.length} · Approved loan balance: AED {money(c.outstanding)} · Manual loans requiring verification: {c.manualLoans}</p>{c.assets.map(a=><p key={a.id}>{a.name} · {a.serial} · {a.status}</p>)}{c.loans.map(l=><p key={l.id}>{l.type} #{l.id} · AED {money(l.remainingBalance)} outstanding · AED {money(l.reservedRecovery)} reserved in approved salary{l.manual?' · Manual / verify settlement':''}</p>)}<p>Approved salary recovery remains outstanding until salary is marked Paid. Recheck current records before clearance.</p></div>}
